"""Build full per-fixture probability tables, not single modal picks."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def read(name):return json.loads((ROOT/'data'/name).read_text(encoding='utf-8'))

def reason(c,p):
    if not p:return '自身记录不足，不使用联赛平均补齐。'
    parts=[]
    for name,s,v in [(c['home_team'],p['home_inputs'],'home'),(c['away_team'],p['away_inputs'],'away')]:
        same=[r for r in s['rows'] if r['venue']==v];current=[r for r in same if r['own_season']];rows=(current if len(current)>=2 else same)[:3]
        parts.append(f"{name}近{len(rows)}个{'主场' if v=='home' else '客场'}进{sum(r['goals_for'] for r in rows)}球、失{sum(r['goals_against'] for r in rows)}球")
    return '；'.join(parts)+'。'

CSS='''
[hidden]{display:none!important}:root{--ink:#192f49;--muted:#61748b;--blue:#2856ac;--line:#dce5ef}*{box-sizing:border-box}body{margin:0;background:#f1f5fa;color:var(--ink);font:14px/1.7 'Microsoft YaHei','PingFang SC',sans-serif}button,input,select{font:inherit}a{color:var(--blue);text-underline-offset:4px}:focus-visible{outline:3px solid #d88e28;outline-offset:3px}.wrap{max-width:1510px;margin:auto;padding:0 28px}header{background:#fff;border-bottom:1px solid var(--line)}.top{display:flex;align-items:center;justify-content:space-between;padding-top:21px;padding-bottom:21px}.brand{font-weight:700;font-size:18px;text-decoration:none;color:var(--ink)}nav{display:flex;gap:25px}nav a{text-decoration:none}nav [aria-current]{font-weight:700;border-bottom:2px solid var(--blue)}.hero{padding-top:30px}.eyebrow{font-size:12px;letter-spacing:.12em;color:var(--blue)}h1{font:600 clamp(28px,3vw,40px)/1.4 'STSong','SimSun',serif;margin:9px 0 10px}.intro,.stamp{color:var(--muted)}.stamp{font-size:12px;margin:16px 0 22px}.leaders{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-bottom:22px}.leader{background:#fff;border:1px solid var(--line);border-left:4px solid #c76d37;border-radius:9px;padding:17px 22px}.leader.low{border-left-color:#326ea6}.leader .label{color:#945022;font-size:12px;font-weight:700}.leader.low .label{color:#326598}.leader strong{display:block;font-size:19px;margin:6px 0}.leader p{margin:0;color:var(--muted);font-size:13px}.leader b{color:var(--ink)}.toolbar{display:flex;align-items:center;gap:13px;flex-wrap:wrap;padding:15px;background:#fff;border:1px solid var(--line);border-radius:10px}.views{display:flex;gap:5px;flex-wrap:wrap}.views button{background:#f2f5fa;color:#49617c;border:1px solid transparent;border-radius:6px;padding:8px 11px;cursor:pointer}.views button[aria-pressed=true]{background:#e6edfc;color:#214c9c;border-color:#b9ccef}label{display:flex;align-items:center;gap:7px;color:var(--muted);font-size:12px}select,input{padding:8px;border:1px solid #cbd7e6;border-radius:6px;background:#fff;color:var(--ink);max-width:100%}input{width:160px}.legend{display:flex;gap:15px;align-items:center;flex-wrap:wrap;margin:15px 0 9px;color:var(--muted);font-size:12px}.swatch{display:inline-block;width:15px;height:12px;border-radius:2px;vertical-align:middle;margin-right:5px}.count{font-size:12px;color:var(--muted);margin:8px 0 12px}.table-wrap{overflow:auto;max-height:76vh;background:#fff;border:1px solid #d3deeb;border-radius:10px;position:relative;isolation:isolate}.prob-table{border-collapse:separate;border-spacing:0;width:100%;min-width:1475px;font-size:13px;font-variant-numeric:tabular-nums}.prob-table th,.prob-table td{padding:13px 8px;border-bottom:1px solid var(--line);text-align:center;white-space:nowrap}.prob-table thead th{background:#eaf0f8;color:#42607f;font-size:12px;position:sticky;top:0;z-index:3;height:49px}.prob-table thead .fixture{z-index:5}.fixture{position:sticky;left:0;z-index:2;min-width:234px;width:234px;max-width:234px;text-align:left!important;background:#fff;box-shadow:2px 0 4px #2949660d}.fixture .meta{overflow:hidden;text-overflow:ellipsis;font-size:11px;color:var(--muted)}.fixture strong{display:block;font-size:13px;white-space:normal;line-height:1.6;margin:4px 0}.fixture button{background:none;border:0;padding:0;color:var(--blue);font-size:11px;cursor:pointer}.bucket{min-width:62px}.tail{min-width:83px;border-left:1px solid #d5dfeb}.tail.low{background:#eef4fc;color:#234e7b}.tail.big{background:#fff3e9;color:#85421d}.tail.extreme{background:#f9e8e3;color:#8b3f31}.tail.six{background:#f2edf8;color:#65467b}.tail span{display:block;font-size:9px;font-weight:400;opacity:.8}.status{min-width:112px;font-size:11px;color:var(--muted)}.flag{display:inline-block;border:1px solid #dfc2a9;background:#fff5eb;border-radius:4px;color:#874b25;padding:2px 5px}.flag.low{border-color:#b9cde3;background:#edf4fd;color:#2b5d90}.reason td{text-align:left;white-space:normal;background:#f8fafd;color:#465e79;padding:15px 22px;font-size:13px}.reason[hidden]{display:none}.missing td{color:#96a2b1;background:#fafbfd}.empty{padding:35px!important;color:var(--muted)}.note{color:var(--muted);font-size:12px;margin:12px 0}.method{background:#fff;border:1px solid var(--line);border-radius:9px;margin-top:22px;padding:20px 23px;color:var(--muted);font-size:13px}.method summary{color:var(--blue);cursor:pointer;font-weight:600}.paging{display:flex;justify-content:center;gap:18px;align-items:center;margin:18px 0}.paging button{border:1px solid #c7d5e6;background:#fff;color:var(--blue);border-radius:5px;padding:7px 14px;cursor:pointer}.paging button:disabled{opacity:.4}footer{padding:28px 0 35px;color:var(--muted);font-size:12px}.scroll-hint{display:none}.mobile-tails{display:none}.skip{position:fixed;top:-100px;background:#fff;padding:8px;z-index:20}.skip:focus{top:0}@media(max-width:760px){.wrap{padding-left:15px;padding-right:15px}.top{padding-top:17px;padding-bottom:17px}.brand{font-size:16px}nav{gap:17px;font-size:13px}.hero{padding-top:24px}.leaders{grid-template-columns:1fr;gap:12px}.leader{padding:14px 17px}.leader strong{font-size:17px}.toolbar{gap:11px}.views{width:100%}.views button{font-size:12px}.toolbar label{flex:1;min-width:130px}.toolbar select,.toolbar input{min-width:0;flex:1;width:100%}.fixture{min-width:164px;width:164px;max-width:164px}.fixture strong{font-size:12px}.prob-table{min-width:1370px}.prob-table th,.prob-table td{padding-left:7px;padding-right:7px}.mobile-tails{display:block;font-size:10px;white-space:normal;color:#486580}.scroll-hint{display:block;color:var(--blue);font-size:12px;margin:9px 0}.legend{gap:8px 12px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}
'''
JS='''
const D=JSON.parse(document.getElementById('board-data').textContent),history=D.mode==='history';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=p=>(p*100).toFixed(1)+'%',league=document.getElementById('league'),sort=document.getElementById('sort'),search=document.getElementById('search');let view='all',page=0;const size=history?30:100;
for(const l of [...new Set(D.matches.map(r=>r.league))].sort()){const o=document.createElement('option');o.value=l;o.textContent=l;league.append(o)}
const eligible=D.matches.filter(r=>r.p),ranked=key=>[...eligible].sort((a,b)=>b[key]-a[key]||a.id.localeCompare(b.id));const highIds=new Set(ranked('five').slice(0,3).map(r=>r.id)),lowIds=new Set(ranked('low').slice(0,3).map(r=>r.id));
function leaders(){for(const [key,id,kind] of [['five','big-leader','big'],['low','low-leader','low']]){const r=ranked(key)[0];document.getElementById(id).innerHTML=r?`<div class="label">${kind==='big'?'高进球相对前列 · 按5球以上排序':'低进球相对前列 · 按0–1球排序'}</div><strong>${esc(r.home)} — ${esc(r.away)}</strong><p>${kind==='big'?`5球以上 <b>${pct(r.five)}</b> · 6球以上 <b>${pct(r.six)}</b>`:`0–1球合计 <b>${pct(r.low)}</b> · 0球 <b>${pct(r.p[0])}</b>`}</p>`:'资料不足'}}
function heat(p){const c=p>=.30?['#65aa98','#123f33']:p>=.20?['#acd2c8','#204d40']:p>=.10?['#dcece9','#345d52']:['#f0f5f7','#607782'];return `background:${c[0]};color:${c[1]}`}
function row(r){const status=!r.p?(r.started?'已开赛未预测':'资料不足'):highIds.has(r.id)?'<span class="flag">高进球相对前列</span>':lowIds.has(r.id)?'<span class="flag low">低进球相对前列</span>':'—';const tail=(v,c)=>`<td class="tail ${c}">${r.p?`<b>${pct(v)}</b>`:'—'}</td>`;
return `<tr class="match-row ${r.p?'':'missing'}" data-id="${esc(r.id)}"><th scope="row" class="fixture"><div class="meta">${esc(r.number||r.date)} · ${esc(r.league)} · ${esc(r.time)}</div><strong>${esc(r.home)} — ${esc(r.away)}</strong>${r.p?`<span class="mobile-tails">0–1球 ${pct(r.low)} · 5+ ${pct(r.five)}</span>`:''}<button type="button" class="evidence" data-id="${esc(r.id)}" aria-expanded="false" aria-controls="reason-${esc(r.id)}">看这场依据</button></th><td>${r.p?r.home_mean.toFixed(2):'—'}</td><td>${r.p?r.away_mean.toFixed(2):'—'}</td><td>${r.p?r.mean.toFixed(2):'—'}</td>${r.p?r.p.map((p,i)=>`<td class="bucket" style="${heat(p)}" data-goals="${i}" title="${i===7?'7球及以上':`恰好${i}球`}：${pct(p)}">${pct(p)}</td>`).join(''):'<td class="bucket">—</td>'.repeat(8)}${tail(r.low,'low')}${tail(r.four,'big')}${tail(r.five,'extreme')}${tail(r.six,'six')}<td class="status">${history?r.actual+'球':status}</td></tr><tr class="reason" id="reason-${esc(r.id)}" hidden><td colspan="17">${esc(r.reason)}${r.p?`<br>总预期进球 ${r.mean.toFixed(2)}。未充分校准的模型试算，仅90分钟。`:''}</td></tr>`}
function render(){const q=search.value.trim().toLowerCase();let rows=D.matches.filter(r=>(!league.value||r.league===league.value)&&(!q||(r.home+r.away+r.number+r.league).toLowerCase().includes(q)));const key=sort.value;rows.sort((a,b)=>a.p&&b.p?(key==='time'?a.order-b.order:b[key]-a[key]||a.order-b.order):a.p?-1:b.p?1:a.order-b.order);if(view!=='all')rows=rows.filter(r=>r.p).slice(0,5);const pages=Math.max(1,Math.ceil(rows.length/size));page=Math.min(page,pages-1);document.getElementById('shown').textContent=`显示${rows.length}场 · ${view==='all'?'全部场次':view==='big'?'当前筛选内5球以上概率前五':'当前筛选内0–1球概率前五'}`;document.getElementById('rows').innerHTML=rows.slice(page*size,(page+1)*size).map(row).join('')||'<tr><td colspan="17" class="empty">没有符合条件的比赛，请更换筛选或清空搜索。</td></tr>';document.getElementById('paging').hidden=!history;document.getElementById('page').textContent=`${page+1} / ${pages}`;document.getElementById('prev').disabled=page===0;document.getElementById('next').disabled=page>=pages-1;document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===view)))}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;page=0;sort.value=view==='small'?'low':'five';render()});for(const el of [league,sort,search])el.addEventListener(el===search?'input':'change',()=>{if(el===sort)view='all';page=0;render()});document.getElementById('rows').onclick=e=>{const b=e.target.closest('.evidence');if(!b)return;const r=document.getElementById('reason-'+b.dataset.id);r.hidden=!r.hidden;b.setAttribute('aria-expanded',String(!r.hidden));b.textContent=r.hidden?'看这场依据':'收起依据'};document.getElementById('prev').onclick=()=>{page--;render()};document.getElementById('next').onclick=()=>{page++;render()};leaders();render();
'''

def build(mode,today,validation):
    history=mode=='history';rows=[]
    for order,r in enumerate(validation['reviews'] if history else today['matches']):
        c=r['case'] if history else r.get('case');p=r['prediction'];pp=p['probabilities'] if p else None
        rows.append(dict(id=c['match_id'] if c else str(r['matchId']),home=c['home_team'] if c else r['homeTeamAllName'],away=c['away_team'] if c else r['awayTeamAllName'],number='' if history else r['matchNumStr'],league=c['competition'] if history else r['leagueAbbName'],date=c['date'] if c else r['matchDate'],time='' if history else ('次日 ' if r['matchDate']>today['business_date'] else '')+r['matchTime'][:5],p=pp,low=sum(pp[:2]) if pp else 0,four=sum(pp[4:]) if pp else 0,five=sum(pp[5:]) if pp else 0,six=sum(pp[6:]) if pp else 0,mean=p['total_expected_goals'] if p else None,home_mean=p['home_expected_goals'] if p else None,away_mean=p['away_expected_goals'] if p else None,reason=(reason(c,p) if c else '采集时比赛已开始，未发布本版赛前预测。')+r.get('risk_text',''),started=not history and r['verdict']=='started',order=order,actual=r.get('actual_total_goals_90')))
    payload=json.dumps(dict(mode=mode,matches=rows),ensure_ascii=False,separators=(',',':')).replace('<','\\u003c');stamp=today['forecast_at'][:19].replace('T',' ')
    title='历史概率与实际总进球' if history else '从两端找比赛'
    note=f"{len(validation['reviews'])}场历史回放。" if history else f"{sum(bool(r['prediction']) for r in today['matches'])}场独立试算；其余{sum(not bool(r['prediction']) for r in today['matches'])}场不补造概率。"
    heads=''.join(f'<th scope="col">{i if i<7 else "7+"}球</th>' for i in range(8))
    legend=''.join(f'<span><i class="swatch" style="background:{c}"></i>{t}</span>' for c,t in [('#f0f5f7','低于10%'),('#dcece9','10–20%'),('#acd2c8','20–30%'),('#65aa98','30%以上')])
    page=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} · 单场观察</title><style>{CSS}</style></head><body><a class="skip" href="#main">跳到概率表</a><header><div class="wrap top"><a class="brand" href="index.html">单场观察</a><nav aria-label="主导航"><a href="index.html" {'aria-current="page"' if not history else ''}>今日比赛</a><a href="review.html">昨日复盘</a><a href="validation.html" {'aria-current="page"' if history else ''}>历史回放</a></nav></div></header><main class="wrap" id="main"><section class="hero"><div class="eyebrow">{'2026.10.01 — 10.30 / 回顾性验证' if history else today['business_date']+' / 竞彩营业日'}</div><h1>{title}</h1><p class="intro">完整看0–7+球概率。抓高进球看5球以上；抓极低进球看0–1球。</p><p class="stamp">赛前快照 {stamp}（北京时间） · v3冻结模型 · {note} · 低置信研究观察</p></section><section class="leaders" aria-label="两端相对排名"><div id="big-leader" class="leader"></div><div id="low-leader" class="leader low"></div></section><div class="toolbar" role="search" aria-label="筛选与排序"><div class="views"><button type="button" data-view="all" aria-pressed="true">全部比赛</button><button type="button" data-view="big" aria-pressed="false">看大球前五</button><button type="button" data-view="small" aria-pressed="false">看极小球前五</button></div><label for="league">赛事<select id="league"><option value="">全部赛事</option></select></label><label for="sort">排序<select id="sort"><option value="five">5球以上 · 高到低</option><option value="four">4球以上 · 高到低</option><option value="six">6球以上 · 高到低</option><option value="low">0–1球 · 高到低</option><option value="time">原始场次顺序</option></select></label><label for="search">球队<input type="search" id="search" placeholder="球队或编号" autocomplete="off"></label></div><div class="legend" aria-label="单球概率颜色图例">单球概率颜色：{legend}</div><p id="shown" class="count" role="status" aria-live="polite"></p><p class="scroll-hint">左右滑动看完整概率，左侧比赛名称固定。</p><div class="table-wrap" tabindex="0" role="region" aria-label="总进球概率表，可横向滚动"><table class="prob-table"><thead><tr><th scope="col" class="fixture">比赛 / 依据</th><th scope="col">主队预期</th><th scope="col">客队预期</th><th scope="col">总预期</th>{heads}<th scope="col" class="tail low">0–1球<span>极低进球合计</span></th><th scope="col" class="tail big">4球以上<span>含4、5、6、7+</span></th><th scope="col" class="tail extreme">5球以上<span>含5、6、7+</span></th><th scope="col" class="tail six">6球以上<span>含6、7+</span></th><th scope="col">{'实际总进球' if history else '相对位置'}</th></tr></thead><tbody id="rows"></tbody></table></div><noscript>请启用JavaScript或查看data/today.json。</noscript><p class="note">7+是7球及以上的合计。右侧合计列有重叠，不能相加；颜色只表示概率大小。“前五 / 前列”是本批次相对排名，不是命中率或强信号认证。</p><div id="paging" class="paging" hidden><button id="prev" type="button">上一页</button><span id="page"></span><button id="next" type="button">下一页</button></div><details class="method"><summary>怎么看这些概率与历史验证</summary><p>单个结果最可能是3球，与5球以上合计仍有明显可能，可以同时成立。抓高比分看5球以上、6球以上；抓极低比分看0–1球。前列只是相对排序：若0–1球约三成，仍有约七成落在其他结果。所有场次目前均为低置信研究观察；前五不代表达到了强信号门槛。</p><p>没有为展示制造大球：每场只用两队自己的历史进失球，做主客权重、时间衰减和自身样本不确定性估计。无联赛均值、大球率、盘口或本场赛果输入。首发、完整逐场xG与球员分钟尚未纳入验证。页面沿用冻结记录，非实时刷新。</p><p>历史同场对照214场，3球以上Brier约0.2467，原算法约0.2614；高概率组仍偏乐观。这个指标不能替代5球以上或0–1球的验证，详见<a href="data/tail-validation.json">两端专门回放</a>。10月结果此前已被查看，属于回顾性复算，不是盲测。</p><p><a href="RESEARCH.md">方法来源</a> · <a href="data/today.json">完整概率与逐队输入</a> · <a href="README.md">复现说明</a></p></details></main><footer class="wrap">仅90分钟总进球，不含加时和点球。以上仅为公开信息整理后的娱乐分析，不构成任何购彩建议，请理性参考。</footer><script id="board-data" type="application/json">{payload}</script><script>{JS}</script></body></html>'''
    (ROOT/('validation.html' if history else 'index.html')).write_text(page,encoding='utf-8')

if __name__=='__main__':
    today=read('today.json');validation=read('validation.json')
    build('today',today,validation);build('history',today,validation)
    print('Built full probability tables and both tail rankings')
